export function equipmentAPI(ITEMS){
 const definition=key=>ITEMS.find(i=>i.key===key),list=v=>Array.isArray(v)?v:typeof v==='string'?[v]:[];
 const trim=a=>{while(a.length&&!a.at(-1))a.pop();return a};
 function normalizeEquipment(state){const out={},used=new Set();for(const key of state.roster||[]){const types=new Set(),slots=[];const raw=list(state.equipment?.[key]),repair=raw.length>3,valid=repair?raw.filter(uid=>{const instance=state.inventory?.find(i=>i.uid===uid);if(!instance||!definition(instance.key)||used.has(uid)||types.has(instance.key))return false;types.add(instance.key);return true}).slice(0,3):raw.slice(0,3);types.clear();for(const [slot,uid]of valid.entries()){const instance=state.inventory?.find(i=>i.uid===uid);slots[slot]=null;if(!instance||!definition(instance.key)||used.has(uid)||types.has(instance.key))continue;slots[slot]=uid;used.add(uid);types.add(instance.key)}if(trim(slots).length)out[key]=slots}return out}
 function heldItems(state,key){return list(state.equipment?.[key]).slice(0,3).flatMap((uid,slot)=>{const instance=state.inventory?.find(i=>i.uid===uid),d=definition(instance?.key);return d?[{...d,uid,slot}]:[]})}
 function combineItems(keys){const defs=[...new Set(list(keys))].map(definition).filter(Boolean).slice(0,3),total={items:defs,keys:defs.map(i=>i.key),key:defs[0]?.key,name:defs.map(i=>i.name).join(' · '),desc:defs.map(i=>i.desc).join(' · ')};for(const stat of['atk','def','speed','hp','regen','cadence'])total[stat]=defs.reduce((n,i)=>n+(i[stat]||0),0);return total}
 const held=(state,key)=>combineItems(heldItems(state,key).map(i=>i.key));
 function equipSlot(state,key,slot,uid){if(!state.roster.includes(key)||!Number.isInteger(slot)||slot<0||slot>2)return false;const instance=state.inventory.find(i=>i.uid===uid);if(!instance||!definition(instance.key))return false;const next=normalizeEquipment(state),target=heldItems({...state,equipment:next},key);if(target.some(i=>i.slot!==slot&&i.key===instance.key)||next[key]?.[slot]===uid)return false;for(const k of Object.keys(next)){next[k]=trim(next[k].map(id=>id===uid?null:id));if(!next[k].length)delete next[k]}next[key]||=[];while(next[key].length<=slot)next[key].push(null);next[key][slot]=uid;state.equipment=next;return true}
 function equip(state,uid,key){const slots=normalizeEquipment(state)[key]||[],slot=[0,1,2].find(i=>!slots[i]);return slot!==undefined&&equipSlot(state,key,slot,uid)}
 function unequip(state,key,uid=null){const next=normalizeEquipment(state);if(!next[key]||(uid!==null&&!next[key].includes(uid)))return false;if(uid===null)delete next[key];else{next[key]=trim(next[key].map(id=>id===uid?null:id));if(!next[key].length)delete next[key]}state.equipment=next;return true}
 return{normalizeEquipment,heldItems,combineItems,held,equip,equipSlot,unequip};
}
